/**
 * Story 12 byte fixtures.
 *
 * The unit tests and the integration tests cannot read `tests/fixtures/images/`
 * (workerd has no filesystem, and an integration test must not touch one), so
 * the small byte sequences they need are *built here* instead. The PNG is a real
 * PNG — a header, an uncompressed (`stored`) zlib stream and correct CRCs — so a
 * browser or a Worker looking at its bytes sees exactly what it would see in a
 * screenshot. The other formats only have to be *recognisable by their magic
 * bytes*, which is all `sniffImageType` can ever look at.
 *
 * Real, decodable files (for a browser to actually draw) live in
 * `tests/fixtures/images/`, generated by `tests/fixtures/make-image-fixtures.py`.
 */

/** A real 8-bit truecolour PNG, built row by row. `size` x `size` pixels. */
export function pngBytes(width = 4, height = 4): Uint8Array<ArrayBuffer> {
  const signature = Uint8Array.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]);

  const ihdr = new Uint8Array(13);
  writeUint32(ihdr, 0, width);
  writeUint32(ihdr, 4, height);
  ihdr[8] = 8; // bit depth
  ihdr[9] = 2; // colour type: truecolour
  ihdr[10] = 0; // compression
  ihdr[11] = 0; // filter
  ihdr[12] = 0; // interlace

  const rowLength = 1 + width * 3;
  const raw = new Uint8Array(rowLength * height);
  for (let y = 0; y < height; y += 1) {
    const row = y * rowLength;
    raw[row] = 0; // filter: none
    for (let x = 0; x < width; x += 1) {
      raw[row + 1 + x * 3] = (x * 16) % 256;
      raw[row + 1 + x * 3 + 1] = (y * 16) % 256;
      raw[row + 1 + x * 3 + 2] = 128;
    }
  }

  return concat(
    signature,
    chunk("IHDR", ihdr),
    chunk("IDAT", zlibStored(raw)),
    chunk("IEND", new Uint8Array(0)),
  );
}

/** A JPEG: `FF D8 FF` … `FF D9`, with a JFIF APP0 marker. */
export function jpegBytes(): Uint8Array<ArrayBuffer> {
  return Uint8Array.from([
    0xff, 0xd8, 0xff, 0xe0, 0x00, 0x10, // SOI, APP0
    0x4a, 0x46, 0x49, 0x46, 0x00, // "JFIF\0"
    0x01, 0x01, 0x00, 0x00, 0x01, 0x00, 0x01, 0x00, 0x00,
    0xff, 0xd9, // EOI
  ]);
}

/** An animated GIF89a header (enough for sniffing; the disk fixture is animated). */
export function gifBytes(): Uint8Array<ArrayBuffer> {
  return concat(ascii("GIF89a"), Uint8Array.from([0x90, 0x01, 0x90, 0x01, 0x87, 0x00, 0x00]));
}

/** A WebP: `RIFF`, the size, `WEBP`, then a `VP8 ` chunk. */
export function webpBytes(): Uint8Array<ArrayBuffer> {
  const payload = ascii("VP8 ");
  const size = new Uint8Array(4);
  writeUint32(size, 0, 8);
  const data = new Uint8Array(8);
  return concat(ascii("RIFF"), size, ascii("WEBP"), payload, data);
}

/** An SVG with a script in it: never an accepted image, whatever its name says. */
export function svgBytes(): Uint8Array<ArrayBuffer> {
  return ascii('<svg xmlns="http://www.w3.org/2000/svg" width="10" height="10"><script>alert(1)</script></svg>');
}

/** A PDF's first bytes. */
export function pdfBytes(): Uint8Array<ArrayBuffer> {
  return concat(ascii("%PDF-1.4\n1 0 obj\n"), ascii("<< /Type /Catalog >>\nendobj\n"));
}

/** A PNG cut off before its signature is complete. */
export function truncatedPngBytes(): Uint8Array<ArrayBuffer> {
  return Uint8Array.from([0x89, 0x50, 0x4e, 0x47]);
}

/** A PNG whose compressed data is cut in half: the magic bytes are still PNG's. */
export function corruptPngBytes(): Uint8Array<ArrayBuffer> {
  const png = pngBytes(8, 8);
  return png.subarray(0, Math.floor(png.length / 2));
}

/** `bytes` repeated to an exact length, prefixed by a format's magic bytes. */
export function bytesOfLength(length: number, magic: Uint8Array = jpegBytes()): Uint8Array<ArrayBuffer> {
  const out = new Uint8Array(length);
  out.set(magic.subarray(0, Math.min(magic.length, length)), 0);
  for (let index = magic.length; index < length; index += 1) out[index] = 0x00;
  return out;
}

export function ascii(text: string): Uint8Array<ArrayBuffer> {
  const out = new Uint8Array(text.length);
  for (let index = 0; index < text.length; index += 1) out[index] = text.charCodeAt(index) & 0xff;
  return out;
}

// ---- the PNG plumbing ----------------------------------------------------

function chunk(type: string, data: Uint8Array): Uint8Array<ArrayBuffer> {
  const length = new Uint8Array(4);
  writeUint32(length, 0, data.length);
  return concat(length, ascii(type), data, uint32(crc32(concat(ascii(type), data))));
}

/** A zlib stream made only of `stored` deflate blocks: valid, and no compressor needed. */
function zlibStored(raw: Uint8Array): Uint8Array<ArrayBuffer> {
  const blocks: Uint8Array[] = [Uint8Array.from([0x78, 0x01])];
  for (let offset = 0; offset < raw.length; offset += 65_535) {
    const size = Math.min(65_535, raw.length - offset);
    const block = new Uint8Array(5 + size);
    block[0] = offset + size >= raw.length ? 1 : 0; // final block
    block[1] = size & 0xff;
    block[2] = (size >> 8) & 0xff;
    block[3] = ~size & 0xff;
    block[4] = (size >> 8) & 0xff;
    block.set(raw.subarray(offset, offset + size), 5);
    blocks.push(block);
  }
  if (raw.length === 0) blocks.push(Uint8Array.from([1, 0, 0, 0xff, 0xff]));
  blocks.push(uint32(adler32(raw)));
  return concat(...blocks);
}

function concat(...parts: Uint8Array[]): Uint8Array<ArrayBuffer> {
  const total = parts.reduce((sum, part) => sum + part.length, 0);
  const out = new Uint8Array(total);
  let offset = 0;
  for (const part of parts) {
    out.set(part, offset);
    offset += part.length;
  }
  return out;
}

function writeUint32(target: Uint8Array, offset: number, value: number): void {
  target[offset] = (value >>> 24) & 0xff;
  target[offset + 1] = (value >>> 16) & 0xff;
  target[offset + 2] = (value >>> 8) & 0xff;
  target[offset + 3] = value & 0xff;
}

function uint32(value: number): Uint8Array<ArrayBuffer> {
  const out = new Uint8Array(4);
  writeUint32(out, 0, value);
  return out;
}

let crcTable: Uint32Array | undefined;
function crc32(bytes: Uint8Array): number {
  if (!crcTable) {
    crcTable = new Uint32Array(256);
    for (let n = 0; n < 256; n += 1) {
      let value = n;
      for (let bit = 0; bit < 8; bit += 1) value = value & 1 ? 0xedb88320 ^ (value >>> 1) : value >>> 1;
      crcTable[n] = value >>> 0;
    }
  }
  let crc = 0xffffffff;
  for (const byte of bytes) crc = crcTable[(crc ^ byte) & 0xff] ^ (crc >>> 8);
  return (crc ^ 0xffffffff) >>> 0;
}

function adler32(bytes: Uint8Array): number {
  let a = 1;
  let b = 0;
  for (const byte of bytes) {
    a = (a + byte) % 65521;
    b = (b + a) % 65521;
  }
  return ((b << 16) | a) >>> 0;
}
